ee:variables.ee:set-variable:
%dw 2.0
output application/java
var appPath      = vars.coords.appPath default "."
var nominalPom   = if (appPath == ".") "pom.xml" else (appPath ++ "/pom.xml")
var treePaths    = vars.tree.tree map $.path
// Use nominal path when present; otherwise fall back to first blob pom.xml at any depth
var appPomPath   =
    if (treePaths contains nominalPom) nominalPom
    else ((vars.tree.tree filter ((item) ->
            item."type" == "blob" and item.path matches /(?:^|\/)pom\.xml$/
         ))[0].path) default nominalPom
var maPath       = if (appPath == ".") "mule-artifact.json" else (appPath ++ "/mule-artifact.json")
var maExists     = treePaths contains maPath
// CI workflow: first .github/workflows/*.yml or *.yaml found in tree
var ciPath       = ((vars.tree.tree filter ((item) ->
                       item.path matches /\.github\/workflows\/[^\/]+\.ya?ml$/
                   ))[0].path) default null
// All property names from matrix gating + connectors — needed by step-6 ownerOf()
var allProps     = ((valuesOf(vars.matrix.gating) map $.property)
                    ++ (vars.matrix.connectors map $.property))
---
{
    appPomPath:          appPomPath,
    muleArtifactExists:  maExists,
    muleArtifactPath:    if (maExists) maPath else null,
    ciWorkflowPath:      ciPath,
    allProps:            allProps
}

%dw 2.0
output application/java
import fromBase64 from dw::core::Binaries
// Path normalisation: resolve relative parent paths against the directory of the current pom
fun removeLastSeg(arr: Array): Array =
    if (sizeOf(arr) <= 1) [] else arr[0 to (sizeOf(arr) - 2)]
fun normalizePath(currentPomPath: String, relPath: String): String = do {
    var dir      = if (currentPomPath contains "/")
                       currentPomPath[0 to ((currentPomPath lastIndexOf "/") - 1)]
                   else ""
    var combined = if (dir == "") relPath else (dir ++ "/" ++ relPath)
    var parts    = (combined splitBy "/") filter ($ != "" and $ != ".")
    --- (parts reduce ((seg, acc = []) ->
            if (seg == ".." and !isEmpty(acc)) removeLastSeg(acc)
            else acc ++ [seg]
        )) joinBy "/"
}
var rawBytes   = fromBase64(payload.content replace /[\r\n\t ]/ with "")
var rawContent = rawBytes as String {encoding: "UTF-8"}
var parsedPom  = read(rawContent, "application/xml")
var parentEl      = parsedPom.project.parent
var rawRel        = parentEl.relativePath default null
// Maven default: <parent> present but no <relativePath> ⇒ ../pom.xml
var relForResolve =
    if (parentEl == null) null
    else if (rawRel == null or (rawRel as String) == "") "../pom.xml"
    else (rawRel as String)
var resolved      = if (relForResolve == null) null
                    else normalizePath(vars.appPomPath, relForResolve)
// Directory-form relativePath (no .xml suffix) ⇒ append /pom.xml
var resolvedFile  = if (resolved == null) null
                    else if (resolved matches /.*pom\.xml$/) resolved
                    else (resolved ++ "/pom.xml")
// Only walk parents that live in THIS repo's tree; external/Exchange parents stop the chain
var treePaths     = vars.tree.tree map $.path
var nextPath      = if (resolvedFile != null and (treePaths contains resolvedFile)) resolvedFile
                    else null
---
{
    appPomText:      rawContent,
    chain:           [{ path: vars.appPomPath, pom: parsedPom }],
    nextParentPath:  nextPath
}

