var rawBytes   = fromBase64(payload.content replace /[\r\n\t ]/ with "")
var rawContent = rawBytes as String {encoding: "UTF-8"}
var parsedPom  = read(rawContent, "application/xml")
var parentEl      = parsedPom.project.parent
